headers={'Authorization':'Bearer '+os.environ['APIDECK_API_KEY'],'x-apideck-app-id':os.environ['APIDECK_APP_ID'],'x-apideck-consumer-id':os.environ['APIDECK_CONSUMER_ID'],'x-apideck-service-id':'onedrive'}
def get(path, params=()):
    url=base+path
    if params:
        url += '?' + urllib.parse.urlencode(params)
    return json.loads(urllib.request.urlopen(urllib.request.Request(url, headers=headers),timeout=60).read().decode())
drive_id=next(d['id'] for d in get('/file-storage/drives')['data'] if d.get('name')==os.environ['APIDECK_FILE_STORAGE_DRIVE_NAME'])
run_id=os.environ['ZEALT_RUN_ID']
out=json.loads(open('/home/user/apideck_task/output.log').read())
root=get('/file-storage/files',[('filter[drive_id]',drive_id),('filter[folder_id]','root'),('limit','200')]).get('data') or []
match=[x for x in root if x.get('name')==f'FOLDER-{run_id}' and x.get('type')=='folder']
children=get('/file-storage/files',[('filter[drive_id]',drive_id),('filter[folder_id]',out['folder_id']),('limit','200')]).get('data') or []
expected={f'NOTE-{run_id}-{i}.txt' for i in range(1,4)}
print(json.dumps({
  'matching_root_folder_count': len(match),
  'created_folder_in_root_matches': bool(match and match[0].get('id') == out['folder_id']),
  'child_count': len(children),
  'child_names_match': {x.get('name') for x in children} == expected,
  'created_file_ids_match': {x.get('id') for x in children} == set(out['file_ids']),
}, separators=(',',

